\begin{align}\label{lll}
5^{-n}w&\geq
\left(\frac14-10(n-1)(\tau\sqrt C+2\sqrt{B\tau})\right)^n w.
\end{align}
Choose $\tau_0$ so that
$\frac14-10(n-1)(\tau_0\sqrt C+2\sqrt{B\tau_0})=\frac15$.
\end{proof}
\begin{corollary}[existence for curvature operators]

